pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {W_WALLET} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(this));
    }

    function _run(address sender, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(putAmount > 0 && collectAmount > 0 && unlockTime > block.timestamp);
        vm.assume(address(this).balance >= putAmount);
        vm.assume(collectAmount <= putAmount);
        try c.Put{value: putAmount}(unlockTime) {} catch { return; }
        bool reverted;
        try c.Collect(collectAmount) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(address sender, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        _run(sender, unlockTime, putAmount, collectAmount);
    }

    receive() external payable {}
}
